R=pathlib.Path('.'); base=R/'curricula/DE/Gymnasium/quality/goal-evidence/2026-10-08'; author=base/'biologie-upper-communication-evaluation-sixteen-native-author-technical-resumed-v1'; own=base/'biologie-upper-sixteen-whole-independent-a-resumed-v1'
